/// The refusal statuses a client may see (§7.8).
fn classify<E: rt::MethodError>(oidl_status: i64) -> rt::CallError<E> {
    match E::from_status(oidl_status) {
        Some(error) => rt::CallError::Method(error),
        None if oidl_status == super::super::super::origin_kernel::Error::InvalidArgs.raw() || oidl_status == super::super::super::origin_kernel::Error::NotSupported.raw() || oidl_status == super::super::super::origin_kernel::Error::AccessDenied.raw() => rt::CallError::Refused(oidl_status),
        None => rt::CallError::Undeclared(oidl_status),
    }
}

